    private void BuildInspector(Control owner){var panel=owner.GetNodeOrNull<Control>("../HSplitContainer/PropertiesPanel");if(panel==null)return;var project=StaticData.get_loaded_project();if(project!=null){var state=project.Get("actor_inspector_state").As<Resource>();if(state==null){state=new ActorInspectorState();project.Set("actor_inspector_state",state);}owner.Set("inspector_ui_state",state);}var inspector=NewScript<Control>("res://Workspaces/SceneWorkspace/scripts/Timeline/actor_inspector.gd");owner.Set("inspector",inspector);panel.AddChild(inspector);inspector.SetAnchorsAndOffsetsPreset(Control.LayoutPreset.FullRect);inspector.OffsetLeft=10;inspector.OffsetTop=10;inspector.OffsetRight=-10;inspector.OffsetBottom=-10;panel.CustomMinimumSize=new Vector2(220,panel.CustomMinimumSize.Y);inspector.Theme=owner.Theme;inspector.Set("hints",owner.Get("hints"));_inspector.setup(inspector,Model(owner),owner.Get("registry").As<RefCounted>(),owner.Get("inspector_ui_state").As<Resource>());inspector.Connect("ui_state_changed",new Callable(owner,"_schedule_ui_state_save"));var files=owner.GetNodeOrNull("../../VSplitContainer/FileSystem");if(files!=null&&files.HasSignal("file_resource_opened"))files.Connect("file_resource_opened",new Callable(owner,"_inspect_project_resource"));}
